import 'package:flutter/material.dart';import '../core/domain.dart';import 'admin_console_screen.dart';import 'finance_screen.dart';import 'hospitality_screen.dart';import 'operations_screen.dart';import 'role_dashboard_screen.dart';import 'super_admin_screen.dart';
class RoleWorkspaceScreen extends StatefulWidget{const RoleWorkspaceScreen({super.key,required this.user});final Map<String,dynamic> user;@override State<RoleWorkspaceScreen> createState()=>_RoleWorkspaceScreenState();}
class _RoleWorkspaceScreenState extends State<RoleWorkspaceScreen>{String? route;Widget page(){final r=roleFrom('${widget.user['role']}');if(r==AppRole.superAdmin)return SuperAdminScreen(user:widget.user);switch(route){case'tours':return AdminConsoleScreen(user:widget.user,collection:'tours',title:'Tours');case'destinations':return AdminConsoleScreen(user:widget.user,collection:'destinations',title:'Destinations');case'suppliers':return AdminConsoleScreen(user:widget.user,collection:'suppliers',title:'Suppliers');case'hotels':return HospitalityScreen(user:widget.user);case'bookings':return OperationsScreen(user:widget.user);case'finance':return FinanceScreen(user:widget.user);default:return RoleDashboardScreen(user:widget.user,onOpen:(v)=>setState(()=>route=v));}}
@override Widget build(BuildContext c)=>Scaffold(appBar:route==null?null:AppBar(title:Text(route!),leading:IconButton(onPressed:()=>setState(()=>route=null),icon:const Icon(Icons.arrow_back))),body:page());}
